func HasGatewayAPIKeyWith(preds ...predicate.APIKey) predicate.EvaluationPlan {
	return predicate.EvaluationPlan(func(s *sql.Selector) {
		step := newGatewayAPIKeyStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasRuns applies the HasEdge predicate on the "runs" edge.
func HasRuns() predicate.EvaluationPlan {
	return predicate.EvaluationPlan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, RunsTable, RunsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasRunsWith applies the HasEdge predicate on the "runs" edge with a given conditions (other predicates).
func HasRunsWith(preds ...predicate.EvaluationRun) predicate.EvaluationPlan {
	return predicate.EvaluationPlan(func(s *sql.Selector) {
		step := newRunsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.EvaluationPlan) predicate.EvaluationPlan {
	return predicate.EvaluationPlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.EvaluationPlan) predicate.EvaluationPlan {
	return predicate.EvaluationPlan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.EvaluationPlan) predicate.EvaluationPlan {
	return predicate.EvaluationPlan(sql.NotPredicates(p))
}
